fun describeValue(value: String?): String {
    if (value != null) {
        return value
    } else {
        return "No value"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithString() {
        Assert.assertEquals("Hello", describeValue("Hello"))
    }

    @Test
    fun testWithNull() {
        Assert.assertEquals("No value", describeValue(null))
    }

    @Test
    fun testWithTeamName() {
        Assert.assertEquals("Tribots", describeValue("Tribots"))
    }

    @Test
    fun testWithEmptyString() {
        Assert.assertEquals("", describeValue(""))
    }
}
